import { useState } from "react";

type Field =
  | { kind: "text"; key: string; label: string; value: string }
  | { kind: "number"; key: string; label: string; value: number; min?: number; max?: number; step?: number }
  | { kind: "toggle"; key: string; label: string; value: boolean }
  | { kind: "readonly"; key: string; label: string; value: string };

type Group = { title: string; fields: Field[] };

export function InspectorPanel({ groups }: { groups: Group[] }) {
  const [draft, setDraft] = useState(() =>
    Object.fromEntries(
      groups.flatMap((g) => g.fields).map((f) => [f.key, f.value]),
    ) as Record<string, string | number | boolean>,
  );

  const set = (key: string, value: string | number | boolean) =>
    setDraft((prev) => ({ ...prev, [key]: value }));

  return (
    <div className="insp-root">
      <header className="insp-head">
        <span className="insp-eyebrow">Selection</span>
        <strong>1 object</strong>
      </header>

      {groups.map((group) => (
        <section className="insp-group" key={group.title}>
          <h4 className="insp-group-title">{group.title}</h4>
          {group.fields.map((field) => (
            <div className="insp-row" key={field.key}>
              <label className="insp-label" htmlFor={field.key}>
                {field.label}
              </label>

              {field.kind === "readonly" ? (
                <span className="insp-value-readonly">{String(draft[field.key])}</span>
              ) : field.kind === "toggle" ? (
                <input
                  id={field.key}
                  type="checkbox"
                  checked={Boolean(draft[field.key])}
                  onChange={(e) => set(field.key, e.target.checked)}
                />
              ) : field.kind === "number" ? (
                <input
                  id={field.key}
                  type="number"
                  value={Number(draft[field.key])}
                  min={field.min}
                  max={field.max}
                  step={field.step ?? 1}
                  onChange={(e) => set(field.key, Number(e.target.value))}
                />
              ) : (
                <input
                  id={field.key}
                  type="text"
                  value={String(draft[field.key])}
                  onChange={(e) => set(field.key, e.target.value)}
                />
              )}
            </div>
          ))}
        </section>
      ))}
    </div>
  );
}

