.insp-root {
  width: 280px;
  height: 100%;
  overflow-y: auto;
  padding: 16px;
  background: var(--surface-base, #ffffff);
  border-left: 1px solid var(--line-subtle, #e6e7eb);
  color: var(--text-strong, #17181c);
  font-size: 12px;
}
.insp-head {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-subtle, #e6e7eb);
}
.insp-eyebrow {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted, #6b7280);
}
.insp-group {
  padding: 12px 0;
  border-bottom: 1px solid var(--line-subtle, #e6e7eb);
}
.insp-group-title {
  margin: 0 0 8px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted, #6b7280);
}
.insp-row {
  display: grid;
  grid-template-columns: 88px 1fr;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
}
.insp-label {
  color: var(--text-muted, #6b7280);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.insp-row input[type='text'],
.insp-row input[type='number'] {
  width: 100%;
  padding: 4px 6px;
  font: inherit;
  border-radius: 5px;
  border: 1px solid var(--line-subtle, #e6e7eb);
  background: var(--surface-inset, #fafafa);
  color: inherit;
}
.insp-row input:focus-visible {
  outline: 2px solid var(--accent, #4f46e5);
  outline-offset: 1px;
}
.insp-value-readonly {
  font-family: ui-monospace, monospace;
  font-size: 11px;
  color: var(--text-muted, #6b7280);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
